css:
.fc { direction: rtl; text-align: right; font-family: "Tajawal", "Cairo", "Arial", sans-serif; font-size: 13px; }
.fc table { width: 100%; border-collapse: collapse; }
.fc-head td { border: none; vertical-align: middle; }
.fc-logo { width: 55%; text-align: right; }
.fc-ref-cell { width: 45%; }
.fc-ref th, .fc-ref td { border: 1px solid #333; padding: 7px 8px; text-align: center; }
.fc-ref th { width: 42%; background: #1f2621 !important; color: #fff !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.fc-table { margin-top: 18px; border: 2px solid #333; }
.fc-table th, .fc-table td { border: 1px solid #333; padding: 6px 10px; }
.fc-table th { width: 42%; text-align: center; font-weight: bold; background: #eeeeee !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.fc-table td { text-align: center; }
.fc-title { font-weight: bold; background: #eeeeee !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.fc-subhead th, .fc-subhead td { font-weight: bold; }
